function fileDetail(f){if(!f)return notFound();remember(f);setNav('files');const key='filetext:'+f.id,text=state.edits[key]??f.text??'';main.innerHTML=crumbs('Файлы','files')+header(f.title||f.name,'Исходник, текстовое представление и связанные материалы.','<a class="button primary" href="'+E(getUrl(f))+'" download="'+E(f.name||f.title)+'">Скачать оригинал</a>')+'<div class="article"><div class="file-details"><div><small>Формат</small>'+E((f.extension||'').toUpperCase())+'</div><div><small>Размер</small>'+size(f.bytes||f.blob?.size||0)+'</div><div><small>Задания</small>'+E((f.tasks||[]).join(', ')||'Общий материал')+'</div></div>'+(f.preview_only?'<p class="inline-note">Показан предварительный просмотр. Полное содержимое сохранено в оригинале.</p>':'')+(['py','kum'].includes(f.extension)?editorHTML({id:key,title:'Код из файла',language:f.extension==='kum'?'kumir':'python',code:f.text||'',status:'Исходный файл не меняется'}):'<h2>Текст файла</h2><textarea class="text-editor" data-document="'+f.id+'" aria-label="Текст документа">'+E(text)+'</textarea><div class="workspace-tools"><button class="button small" data-copy-file="'+f.id+'">Копировать текст</button><button class="button small" data-download-text="'+f.id+'">Скачать текст с правками</button><button class="button small" data-reset-document="'+f.id+'">Вернуть исходный текст</button></div><p class="small">Изменения сохраняются в этом браузере. Оригинальный файл сохраняется отдельно.</p>')+(f.tables||[]).map((t,i)=>tableHTML(t,f.id+'_'+i)).join('')+(f.images?.length?'<h2>Изображения в текстовом виде</h2>'+f.images.map(mid=>mediaHTML(mid,{compact:true})).join(''):'')+((f.sources||[]).length?'<h2>Источники</h2>'+f.sources.map(s=>'<p class="source-path">'+E(s)+'</p>').join(''):'')+noteHTML(f.id)+'</div>';afterRender();}
