function render(){editors.clear();const [path,qs='']=(location.hash.slice(1)||'home').split('?'),[view,id]=path.split('/'),p=new URLSearchParams(qs);if(p.has('t'))filters.task=p.get('t');if(p.has('status')){filters.status=p.get('status');if(!p.has('t'))filters.task='';}if(p.has('source'))filters.source=p.get('source');document.body.classList.remove('menu-open');$('#menu-button').setAttribute('aria-expanded','false');switch(view){case'home':home();break;case'tasks':taskList();break;case'task':taskDetail(D.tasks.find(x=>x.id===id)||locals.find(x=>x.id===id));break;case'methods':methods();break;case'patterns':patternList();break;case'pattern':patternDetail(patterns.find(x=>x.id===id));break;case'method':methodDetail(D.methods.find(x=>x.id===id));break;case'lessons':lessonList();break;case'lesson':lessonDetail(D.lessons.find(x=>x.id===id));break;case'files':fileList();break;case'file':fileDetail(fileById(id));break;case'images':images();break;case'image':imageDetail(D.media[id]||locals.find(x=>x.id===id));break;case'workspace':workspace();break;case'review':review();break;case'search':searchView();break;case'custom':customDetail(locals.find(x=>x.id===id));break;default:notFound()}document.title=(main.querySelector('h1')?.textContent||'База знаний')+' · Информатика';afterRender();}
